(()=>{'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString('fr-FR'),role=document.body.dataset.role,isCreator=role==='creator';let incoming={};try{incoming=JSON.parse(decodeURIComponent(location.hash.slice(1)))}catch{}if(incoming.ops)DEMOOPS0291.write(incoming.ops);let db=DEMOOPS0291.read(),tab='overview',selection=null,toastTimer,confirmAction=null,pending=new Map(),sequence=0;
const tabs=[['overview','Vue d’ensemble','◈'],['players','Joueurs et vérifications','♙'],['reports','Signalements','⚑'],['sanctions','Sanctions','⚖'],['gifts','Courriers et cadeaux','✦'],['codes','Codes cadeaux','◇','creator'],['photos','Photos de profil','▣'],['purchases','Achats et remboursements','◉'],['clans','Alliances et tournois','⚐'],['referrals','Parrainages','↗'],['support0304','Assistance joueurs','✉'],['team','Administrateurs','♜','creator'],['botlab','Atelier des châteaux','♜','creator'],['content','Création et équilibrage','✎','creator'],['promotions','Événements et promotions','✧','creator'],['services','Traduction et consommation','☷','creator'],['audit','Journal et contrôles','≡']].filter(t=>isCreator||['overview','sanctions','referrals','support0304'].includes(t[0]));
const btn=(label,action,data='',cls='')=>'<button data-action="'+action+'" '+data+' class="'+cls+'">'+label+'</button>',card=(title,body)=>'<section class="console-card"><h3>'+title+'</h3>'+body+'</section>',pill=(text,cls='')=>'<span class="pill '+cls+'">'+esc(text)+'</span>',empty=t=>'<div class="console-empty">'+t+'</div>',playerOptions=()=>db.players.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.id)+'</option>').join(''),table=(headers,rows)=>'<div class="table-wrap"><table class="console-table"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>',row=(...cells)=>'<tr>'+cells.map(c=>'<td>'+c+'</td>').join('')+'</tr>',field=(label,id,value='',type='text',extra='')=>'<label>'+label+'<input id="'+id+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>',select=(label,id,options)=>'<label>'+label+'<select id="'+id+'">'+options+'</select></label>',options=rows=>rows.map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('');
function toast(text){let el=$('#console-toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000)}
function dialog(title,body,action){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#console-modal').hidden=false;confirmAction=action;$('#dialog-confirm').hidden=!action;$('#dialog-confirm').focus()}
$('#dialog-cancel').onclick=()=>{$('#console-modal').hidden=true;confirmAction=null};$('#dialog-confirm').onclick=async()=>{if(!confirmAction)return;let fn=confirmAction;try{$('#dialog-confirm').disabled=true;await fn();$('#console-modal').hidden=true;confirmAction=null;render();toast('Opération locale enregistrée et journalisée.')}catch(e){toast(e.message)}finally{$('#dialog-confirm').disabled=false}};
function request(type,kind,payload){if(window.opener&&incoming.token)return new Promise((resolve,reject)=>{let id=++sequence;pending.set(id,{resolve,reject});window.opener.postMessage({type,token:incoming.token,kind,payload,requestId:id},'*');setTimeout(()=>{if(pending.has(id)){pending.delete(id);reject(Error('La page du joueur ne répond pas. Rouvre cet espace depuis ses paramètres.'))}},8000)});if(type==='blabox-ops-read')return Promise.resolve(DEMOOPS0291.read());return Promise.resolve(DEMOOPS0291.command(role,kind,payload));}
window.addEventListener('message',e=>{if(e.source!==window.opener||e.data?.token!==incoming.token)return;let q=pending.get(e.data.requestId);if(!q)return;pending.delete(e.data.requestId);if(e.data.error)q.reject(Error(e.data.error));else{db=e.data.ops;DEMOOPS0291.write(db);q.resolve(db)}});
async function commit(kind,p){db=await request('blabox-ops-command',kind,p);DEMOOPS0291.write(db);return db}
function preview(kind,p,title='Vérifier avant validation'){dialog(title,'<p>Simulation locale · aucune opération n’est envoyée à un serveur.</p><pre>'+esc(JSON.stringify(p,null,2))+'</pre>',()=>commit(kind,p))}
function overview(){let active=db.sanctions.filter(s=>s.active&&(s.permanent||s.expiresAt>Date.now())).length;return '<div class="console-grid">'+[['Joueurs locaux',db.players.length,'Comptes de démonstration'],['Signalements ouverts',db.reports.filter(r=>r.status==='open').length,'Dossiers à examiner'],['Sanctions actives',active,'Effets locaux uniquement'],['Opérations journalisées',db.audit.length,'Historique du navigateur']].map(([title,n,note])=>'<article class="console-kpi"><small>'+title+'</small><strong>'+fmt(n)+'</strong><span>'+note+'</span></article>').join('')+'</div><div class="console-columns">'+card('Bienvenue au conseil d’Astral','<p>'+(isCreator?'Tu disposes de tous les outils administrateur. Tu peux nommer, restreindre et révoquer les administrateurs, superviser leurs vérifications de parrainage et publier les réglages locaux.':'Les outils sont limités par tes permissions. Le créateur peut les retirer immédiatement.')+'</p><div class="actions">'+btn('Examiner les signalements','tab','data-tab="reports"')+btn('Préparer un cadeau','tab','data-tab="gifts"','secondary')+'</div><div class="section-note">Les responsables d’alliance ne possèdent aucun de ces droits sur le jeu.</div>')+card('À surveiller','<div class="console-timeline"><div><b>'+db.photos.filter(p=>p.status==='pending').length+' photo(s) à valider</b><p class="muted">Contrôle manuel et motif de refus.</p></div><div><b>'+db.orders.filter(o=>o.status==='credited').length+' reçu(s) simulé(s)</b><p class="muted">Google Play non connecté. Les chiffres ne sont pas des ventes réelles.</p></div><div><b>Services externes non connectés</b><p class="muted">Traduction, mesures D1, comptes et diffusion serveur restent à raccorder.</p></div></div>')+'</div>'+card('Dernières interventions',auditTable(db.audit.slice(0,6)));}
function players(){return card('Comptes et vérifications',table(['Joueur','Progression','Alliance','État','Actions'],db.players.map(p=>row('<span class="profile-dot">'+esc(p.name[0])+'</span><b>'+esc(p.name)+'</b><br><small>'+esc(p.id)+'</small>','Cœur '+p.level+'<br><small>'+esc(p.flag||'FR')+' · '+esc(p.language||'fr')+'</small>',esc(p.clan||'Sans alliance'),pill(p.role==='admin'?'Administrateur':'Joueur')+(p.verification?'<p class="muted">'+esc(p.verification)+'</p>':''),btn('Dossier','player','data-id="'+p.id+'"','secondary')))))+card('Recherche et contrôle','<p>Les dossiers présentent les valeurs locales, l’historique des sanctions et des distributions. Les identités, appareils et achats doivent être vérifiés par le serveur avant toute décision réelle.</p>');}
function reports(){return db.reports.length?db.reports.map(r=>card('Dossier '+esc(r.id)+' '+pill(r.status,r.status==='open'?'warn':''),'<p><b>'+esc(r.playerId)+'</b> · '+esc(r.reason)+'</p><div class="section-note">'+r.messages.map(esc).join('<br>')+'</div><div class="actions">'+btn('Avertir','warn','data-player="'+r.playerId+'"')+btn('Masquer le message','hide','data-player="'+r.playerId+'"','secondary')+btn('Préparer une sanction','go-sanction','data-player="'+r.playerId+'"','danger')+btn('Clore le dossier','report-close','data-id="'+r.id+'"','secondary')+'</div>')).join(''):empty('Aucun signalement.');}
function sanctions(){return '<div class="console-columns">'+card('Préparer une sanction','<div class="console-form">'+select('Joueur','sanction-player',playerOptions())+select('Périmètre','sanction-scope',options([['chat','Discussion'],['game','Accès au jeu'],...(isCreator?[['purchases','Achats'],['gifts','Réception de cadeaux'],['ranked','Combats classés'],['alliance','Recrutement en alliance']]:[])]))+field('Durée en minutes','sanction-minutes',60,'number','min="1" '+(!isCreator?'max="60"':''))+(isCreator?select('Durée définitive','sanction-permanent',options([['no','Temporaire'],['yes','Permanente']])):'<p class="muted">Administrateur : 1 heure maximum, chat ou jeu uniquement. Impossible de sanctionner un administrateur ou le créateur.</p>')+'<label class="wide">Motif<textarea id="sanction-reason" placeholder="Faits constatés, contexte et règle concernée"></textarea></label></div><div class="actions">'+btn('Vérifier la sanction','sanction-preview','','danger')+'</div>')+card('Historique des sanctions',db.sanctions.length?table(['Cible','Périmètre','Fin','État',''],db.sanctions.map(s=>row(esc(s.playerId),esc(s.scope),s.permanent?'Permanente':new Date(s.expiresAt).toLocaleString('fr-FR'),pill(s.active?'Active':'Révoquée',s.active?'danger':''),isCreator&&s.active?btn('Révoquer','sanction-revoke','data-id="'+s.id+'"','secondary'):''))):empty('Aucune sanction.'))+'</div>';}
function rewardFields(){return '<div class="console-form">'+field('Diamants','gift-diamonds',20,'number','min="0"')+field('Or','gift-gold',1000,'number','min="0"')+field('Élixir','gift-elixir',1000,'number','min="0"')+select('Objet','gift-item',options([['','Aucun'],['xp-small','Petite potion XP'],['xp-medium','Potion XP moyenne'],['xp-large','Grande potion XP'],['mana-5','Petite potion de mana'],['health-25','Petite potion de vie'],['speed-300','Accélérateur 5 min'],['speed-3600','Accélérateur 1 h'],['energy-refill','Recharge énergie']]))+field('Quantité de l’objet','gift-item-count',1,'number','min="0"')+(isCreator?select('Héros à offrir','gift-hero','<option value="">Aucun</option>'+GESTION_CATALOGUE.heroes.map(h=>'<option value="'+h.id+'">'+esc(h.name)+'</option>').join(''))+select('Cosmétique','gift-cosmetic','<option value="">Aucun</option>'+GESTION_CATALOGUE.cosmetics.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join(''))+field('XP à offrir','gift-xp',0,'number','min="0"')+select('Héros recevant l’XP','gift-xp-hero',GESTION_CATALOGUE.heroes.map(h=>'<option value="'+h.id+'">'+esc(h.name)+'</option>').join('')):'')+'</div>';}
function reward(){let item=$('#gift-item').value;return {diamonds:+$('#gift-diamonds').value,gold:+$('#gift-gold').value,elixir:+$('#gift-elixir').value,items:item?{[item]:+$('#gift-item-count').value}:{},hero:$('#gift-hero')?.value||'',cosmetic:$('#gift-cosmetic')?.value||'',xp:+($('#gift-xp')?.value||0),xpHero:$('#gift-xp-hero')?.value||''};}
function gifts(){return card('Composer un courrier et son cadeau','<div class="console-form">'+field('Titre','gift-title','Merci, aventuriers !')+select('Destinataires','gift-audience',options([['player','Un joueur'],...(isCreator?[['clan','Une alliance'],['all','Tous les comptes locaux']]:[])]))+select('Joueur','gift-player',playerOptions())+field('Alliance','gift-clan','Les Sentinelles')+'<label class="wide">Message<textarea id="gift-text">Voici un cadeau pour vous remercier.</textarea></label></div><h4>Récompenses par destinataire</h4>'+rewardFields()+'<div class="actions">'+btn('Prévisualiser et vérifier le total','gift-preview')+'</div><p class="muted">'+(isCreator?'Créateur : destinataires collectifs, héros, cosmétiques et XP. Les cadeaux passent par le courrier du joueur et ne sont récupérables qu’une fois.':'Administrateur : un joueur, 100 diamants maximum par cadeau, 500 par jour ; 50 000 or/élixir maximum par cadeau. Aucun héros, cosmétique ou XP.')+'</p>')+card('Distributions',db.gifts.length?table(['Titre','Audience','Par joueur','État',''],db.gifts.slice().reverse().map(g=>row(esc(g.title),g.playerIds.length+' compte(s)',fmt(g.reward.diamonds)+' 💎 · '+fmt(g.reward.gold)+' or · '+fmt(g.reward.elixir)+' élixir',pill(g.status),isCreator&&g.status==='prepared'?btn('Annuler','gift-cancel','data-id="'+g.id+'"','secondary'):''))):empty('Aucune distribution.'));}
function codes(){return card('Créer un code cadeau','<div class="console-form">'+field('Code','code-value','ASTRAL-MERCI','text','maxlength="32"')+select('Type','code-kind',options([['collective','Collectif'],['personal','Personnel']]))+select('Joueur si personnel','code-player',playerOptions())+field('Utilisations maximales','code-limit',100,'number','min="1"')+field('Expiration','code-expiry',new Date(Date.now()+7*86400000).toISOString().slice(0,16),'datetime-local')+'</div><h4>Récompense du code</h4>'+rewardFields()+'<div class="actions">'+btn('Vérifier le code','code-preview')+'</div><p class="muted">Une utilisation par compte. Les codes créés ici fonctionnent dans le courrier de cette démo.</p>')+card('Codes enregistrés',db.codes.length?table(['Code','Limite','Expiration','État',''],db.codes.map(c=>row(esc(c.code),c.usedBy.length+' / '+c.limit,new Date(c.expiresAt).toLocaleDateString('fr-FR'),pill(c.active?'Actif':'Désactivé'),c.active?btn('Désactiver','code-disable','data-id="'+c.id+'"','secondary'):''))):empty('Aucun code créé.'));}
function photos(){return card('Validation des portraits','<p>Examiner l’image, accepter ou refuser avec un motif. Le service réel exige une identité de modérateur distincte de celle du joueur.</p>')+(db.photos.length?db.photos.map(p=>card(esc(p.playerId)+' · '+pill(p.status),'<img class="photo-review" src="'+esc(p.image)+'" alt="Photo soumise"><label>Motif<textarea id="photo-reason-'+p.id+'"></textarea></label><div class="actions">'+btn('Valider','photo-review','data-id="'+p.id+'" data-approved="true" '+(p.status!=='pending'?'disabled':''))+btn('Refuser et rembourser','photo-review','data-id="'+p.id+'" data-approved="false" '+(p.status!=='pending'?'disabled':''),'danger')+'</div>')).join(''):empty('Aucune photo en attente.'));}
function purchases(){const name=id=>db.players.find(p=>p.id===id)?.name||id||'Non renseigné';return card('Achats et cadeaux de diamants','<p class="section-note">Reçus de simulation locale. Les paiements réels et leur vérification restent à raccorder au serveur.</p>'+ (db.orders.length?table(['Date','Acheteur','Lot / bonus','Destination','Montant','Bonus acheteur','État',''],[...db.orders].reverse().map(o=>row(new Date(o.at).toLocaleString('fr-FR'),esc(o.buyerName||name(o.playerId)),o.kind==='bundle'?'<b>'+esc(o.bundleName)+'</b><br><small>'+esc(o.description||[o.contents?.workers?o.contents.workers+' ouvriers':'',o.contents?.hero||'',o.contents?.xpPotions?o.contents.xpPotions+' potions de 1 500 XP':''].filter(Boolean).join(' · '))+'</small>':fmt(o.baseDiamonds)+' + '+fmt(Math.max(0,(o.totalDiamonds||o.baseDiamonds)-o.baseDiamonds))+'<br><b>'+fmt(o.totalDiamonds||o.baseDiamonds)+' diamants</b>',o.giftRecipient?'Cadeau à <b>'+esc(o.recipientName||name(o.giftRecipient))+'</b>':'Pour soi',esc(o.paid||(o.amountMinor!=null?(o.amountMinor/100).toFixed(2)+' €':'Non enregistré')),fmt(o.senderBonus||0)+' diamants',pill(o.status,o.refunded?'danger':''),isCreator&&!o.refunded?btn('Simuler remboursement','order-refund','data-id="'+esc(o.id)+'"','danger'):''))):empty('Aucun achat enregistré.')));}
function legacyPurchases0303(){let total=db.orders.filter(o=>o.status==='credited').reduce((n,o)=>n+(o.baseDiamonds||0),0);return '<div class="console-grid"><article class="console-kpi"><small>Reçus locaux</small><strong>'+db.orders.length+'</strong><span>Aucune vente réelle</span></article><article class="console-kpi"><small>Diamants de base simulés</small><strong>'+fmt(total)+'</strong><span>Hors bonus promotionnels</span></article></div>'+card('État du service','<div class="section-note">Google Play non connecté. Un achat réel doit être vérifié côté serveur, lié à un reçu unique et contrôlé à nouveau lors d’un remboursement. Aucun bouton de cette page ne valide un reçu auprès de Google.</div>')+(isCreator?card('Enregistrer un reçu d’essai','<div class="console-form">'+field('Identifiant unique du reçu','order-id','DEMO-'+Date.now())+select('Joueur','order-player',playerOptions())+field('Diamants de base','order-diamonds',1200,'number','min="1"')+field('Date de l’achat simulé','order-date',new Date().toISOString().slice(0,16),'datetime-local')+'</div><div class="actions">'+btn('Vérifier la simulation','order-preview')+'</div>'):'')+card('Commandes',db.orders.length?table(['Reçu','Joueur','Base','Date','Statut',''],db.orders.map(o=>row(esc(o.id),esc(o.playerId),fmt(o.baseDiamonds),new Date(o.at).toLocaleString('fr-FR'),pill(o.status,o.refunded?'danger':''),isCreator&&!o.refunded?btn('Simuler remboursement','order-refund','data-id="'+o.id+'"','danger'):''))):empty('Aucun reçu d’essai.'));}
function clans(){let groups=[...new Set(db.players.map(p=>p.clan).filter(Boolean))];return card('Alliances locales',table(['Alliance','Membres connus','Vérification'],groups.map(n=>row(esc(n),db.players.filter(p=>p.clan===n).length,pill('Données locales')))))+(isCreator?card('Clôturer un tournoi d’essai','<p>Les récompenses collectives et personnelles sont distinctes. Un identifiant ne peut être clôturé qu’une fois.</p><div class="console-form">'+field('Identifiant du tournoi','tournament-id','TEST-'+new Date().toISOString().slice(0,10))+'<label class="wide">Résultats JSON<textarea id="tournament-rows" class="code">'+esc(JSON.stringify(groups.map((name,i)=>({id:'clan-'+i,clanId:db.players.find(p=>p.clan===name)?.clanId||'clan-'+i,name,wins:5-i,stars:15-i*2,destruction:1200-i*100,duration:600+i*50})),null,2))+'</textarea></label></div><div class="actions">'+btn('Prévisualiser le classement','tournament-preview')+'</div>'):'')+card('Tournois clôturés',db.tournaments.length?db.tournaments.map(t=>'<h4>'+esc(t.id)+'</h4>'+table(['Rang','Alliance','Victoires','Étoiles'],t.rows.map(r=>row(r.rank,esc(r.name),r.wins,r.stars)))).join(''):empty('Aucun tournoi clôturé.'));}
function referrals(){return card('Liens de parrainage',db.links.length?table(['Parrain','Filleul','Validation',''],db.links.map(l=>row(esc(l.parent),esc(l.child),pill(l.qualified?'Récompensé':'Conditions à vérifier',l.qualified?'':'warn'),isCreator&&!l.qualified?btn('Vérifier les conditions','referral-qualify','data-child="'+l.child+'"','secondary'):''))):empty('Aucun lien de parrainage.'))+(isCreator?card('Associer deux comptes d’essai','<div class="console-form">'+select('Parrain','referral-parent',playerOptions())+select('Filleul','referral-child',playerOptions())+'</div><div class="actions">'+btn('Vérifier le lien','referral-preview')+btn('Traiter les bonus arrivés à 24 h','referral-settle','','secondary')+'</div><p class="muted">Auto-parrainages, cycles, doubles associations et doubles crédits sont refusés. Les remboursements annulent les bonus liés.</p>'):'')+card('Bonus de 5 %',db.referralCredits.length?table(['Commande','Bénéficiaire','Diamants','État'],db.referralCredits.map(c=>row(esc(c.orderId),esc(c.playerId),fmt(c.diamonds),pill(c.reversed?'Récupéré':'Crédit local',c.reversed?'warn':'')))):empty('Aucun bonus échu.'));}
function team(){return card('Créateur · administrateur des administrateurs','<p>Le propriétaire conserve tous les droits. Lui seul peut nommer ou révoquer les administrateurs, modifier leurs permissions et superviser leurs vérifications de parrainage. Aucun administrateur ne peut sanctionner le créateur ou un autre administrateur.</p><div class="console-form">'+select('Compte à nommer','admin-player',playerOptions())+'</div><h4>Permissions déléguées</h4><div class="permissions">'+RULES0291.PERMISSIONS.admin.map(p=>'<label><input type="checkbox" name="permission" value="'+p+'" checked>'+p+'</label>').join('')+'</div><div class="actions">'+btn('Vérifier la nomination','admin-preview')+'</div>')+card('Équipe',table(['Compte','Droits','État',''],db.admins.map(a=>row(esc(a.name)+'<br><small>'+esc(a.id)+'</small>',a.permissions.map(esc).join('<br>'),pill(a.active?'Actif':'Révoqué'),a.active?btn('Modifier les droits','admin-edit','data-id="'+a.id+'"','secondary')+btn('Révoquer les droits','admin-remove','data-id="'+a.id+'"','danger'):''))));}
function catalogue(kind){return kind==='hero'?GESTION_CATALOGUE.heroes:kind==='troop'?GESTION_CATALOGUE.troops:GESTION_CATALOGUE.structures.filter(s=>kind==='defense'?s.asset?.startsWith('defense:'):s.asset?.startsWith('building:'));}
function content(){let kind=selection?.kind||'hero',items=catalogue(kind),item=selection?.data||items[0];return '<div class="console-columns">'+card('Atelier de contenu','<p>Modifier un catalogue existant, préparer un brouillon, le prévisualiser et publier une révision locale. Les nouvelles mécaniques doivent être développées et validées avant un raccordement serveur.</p><div class="console-form">'+select('Famille','content-kind',options([['hero','Héros'],['troop','Classes'],['building','Bâtiments'],['defense','Défenses']]))+select('Élément','content-item',items.map(i=>'<option value="'+i.id+'">'+esc(i.name)+'</option>').join(''))+'<label class="wide">Définition JSON<textarea id="content-json" class="code">'+esc(JSON.stringify(item,null,2))+'</textarea></label></div><div class="actions">'+btn('Valider et prévisualiser','content-preview')+btn('Enregistrer un brouillon','content-save','','secondary')+'</div>')+card('Brouillons et révisions',db.content.length?db.content.map(c=>'<h4>'+esc(c.name)+' · '+pill(c.status)+'</h4><p class="muted">'+esc(c.kind)+' · '+c.history.length+' version(s) antérieure(s)</p><div class="actions">'+btn('Publier localement','content-publish','data-id="'+c.id+'"')+btn('Revenir à la version précédente','content-rollback','data-id="'+c.id+'" '+(!c.history.length?'disabled':''),'secondary')+'</div>').join(''):empty('Aucun brouillon.'))+'</div>';}
function promotions(){let now=new Date(),month=now.toISOString().slice(0,7),m=RULES0291.monthlyOffer(month);return card('Règles des offres','<p>Première offre : +50 % sur un achat de diamants suivant le premier achat, valable six jours à partir de son affichage. Offre personnelle unique.</p><p>Offre mensuelle globale : probabilité 25 %, début entre le 3 et le 15, durée six jours, +20 % sur les achats éligibles. Le bonus de diamants le plus avantageux est prioritaire ; aucun cumul. Deux offres au maximum sont affichées simultanément, les autres attendent une place.</p><div class="section-note">Simulation mensuelle '+month+' : '+(m.activeMonth?'offre prévue':'aucune offre ce mois')+' · fenêtre '+new Date(m.start).toLocaleDateString('fr-FR')+' → '+new Date(m.end).toLocaleDateString('fr-FR')+'. Le tirage réel partagé doit être produit et signé par le serveur.</div><h4>Exemple de présentation</h4><p>14 000 + 2 800 = <b>16 800 diamants</b>.</p>')+card('Catalogue des promotions 0.30.5',"<p>Deux offres simultanées au maximum. Les offres en attente gardent leur durée complète. Chaque visuel utilise les sprites originaux des héros et objets ; les choix de héros sont reflétés dans l’encart et le reçu.</p><p>Valeurs barrées estimées : 100 diamants = 0,99 €. Ce ne sont pas d’anciens prix réellement pratiqués. Les boutons de test sont dans Paramètres → Tests. Le lot de 30 jours vaut 38 600 diamants : 5 × 1 jour + 430 × 1 h + 400 × 15 min + 840 × 5 min.</p><div class=\"scroll\"><table><thead><tr><th>Offre</th><th>Prix</th><th>Durée affichée</th><th>Déclenchement</th></tr></thead><tbody><tr><td>Offre unique de diamants +50 %</td><td>Selon le lot</td><td>6 jours</td><td>Après le premier achat payé ; bonus sur un achat de diamants suivant.</td></tr><tr><td>Festival des trésors +20 %</td><td>Selon le lot</td><td>6 jours</td><td>Événement mensuel : probabilité de 25 %, début entre le 3 et le 15. Le meilleur bonus actif est retenu, sans cumul.</td></tr><tr><td>2 ouvriers permanents + Tiko</td><td>9,99 €</td><td>7 jours</td><td>Achat d'un ouvrier, en dehors de celui offert dans le tutoriel/démo ; Tiko doit être absent de l'équipe.</td></tr><tr><td>Drac catalan + 15 potions de 1 500 XP</td><td>49,99 €</td><td>15 jours</td><td>Achat d'un héros épique, ou après 110 jours de compte si Drac n'est pas possédé et que son offre unique n'a pas été consommée/expirée.</td></tr><tr><td>20 potions de 1 500 XP</td><td>9,99 € ; référence 19,99 €</td><td>6 jours</td><td>Achat d'une potion de 500 XP.</td></tr><tr><td>3 héros rares non possédés, au choix</td><td>14,99 €</td><td>7 jours</td><td>Premier achat d'un héros en boutique. Il doit rester au moins trois héros rares à obtenir.</td></tr><tr><td>40 potions de 1 500 XP</td><td>19,99 € ; référence 39,98 €</td><td>15 jours</td><td>48 heures après l'achat du lot de trois héros rares.</td></tr><tr><td>Duo épique : un acheté, un offert</td><td>Prix estimé du héros attribué</td><td>30 jours, deux présentations maximum</td><td>Deux mois calendaires après le premier achat payé. Un épique non possédé est attribué et mémorisé ; le second est choisi par le joueur, dans la même catégorie. Nouvelle présentation possible 45 jours après la fin du premier compte à rebours. La seconde est la dernière.</td></tr><tr><td>Lot de 30 jours d'accélération</td><td>152,86 € ; référence 382,14 €, −60 %</td><td>15 jours par présentation</td><td>Achat d'un accélérateur en diamants ou en boutique de clan après 85 jours de compte, puis nouvel achat après 160 jours. Les deux présentations ne sont pas affichées simultanément.</td></tr><tr><td>Morghul + 15 potions de 1 500 XP</td><td>49,99 €</td><td>15 jours</td><td>Après 110 jours de compte, si Morghul n'est pas possédé. Si ni Drac ni Morghul ne sont possédés, leurs deux offres peuvent être proposées, sous réserve des offres uniques déjà consommées/expirées.</td></tr><tr><td>48 accélérateurs d'une heure</td><td>0,99 € ; 1 920 diamants estimés à 19,01 €</td><td>5 jours</td><td>14 jours après le premier achat payé.</td></tr><tr><td>48 potions de 500 XP</td><td>1,99 € ; 2 160 diamants estimés à 21,38 €</td><td>5 jours</td><td>14 jours après le premier achat payé.</td></tr><tr><td>Castillet + jardinière offerte</td><td>1,99 € ; référence estimée 15,39 €</td><td>15 jours</td><td>À partir du niveau 8, si le Castillet n'est pas déjà possédé. La jardinière est disponible gratuitement dans l'inventaire pour être placée.</td></tr></tbody></table></div>")+card('Brouillon d’événement','<div class="console-form">'+field('Nom','promotion-title','Fête d’Astral')+field('Début','promotion-start',new Date(Date.now()+86400000).toISOString().slice(0,16),'datetime-local')+field('Fin','promotion-end',new Date(Date.now()+7*86400000).toISOString().slice(0,16),'datetime-local')+field('Bonus (%)','promotion-rate',20,'number','min="0" max="50"')+'</div><div class="actions">'+btn('Enregistrer un brouillon','promotion-preview')+'</div>')+card('Programmation locale',db.promotions.length?db.promotions.map(p=>'<p><b>'+esc(p.title)+'</b> · '+pill(p.status)+' · +'+Math.round(p.rate*100)+' %</p>').join(''):empty('Aucun événement préparé.'));}
function services(){return card('Traduction Cloudflare · configuration prévue','<div class="section-note">Service non connecté. Aucun texte n’est envoyé à une API, aucun résultat simulé n’est présenté comme une traduction réelle.</div><div class="console-form">'+select('Fonction prévue','translation-enabled',options([['off','Désactivée'],['on','Activée après raccordement']]))+field('Plafond mensuel configuré (€)','translation-budget',db.config.translationBudgetEur,'number','min="0"')+'</div><div class="actions">'+btn('Enregistrer la configuration locale','translation-save')+'</div><p class="muted">Cache par identifiant de message et langue cible, déduplication des demandes concurrentes, validation côté Worker et blocage avant dépassement du budget. Le plafond est un choix de configuration, pas une facture Cloudflare mesurée.</p>')+card('Mesures D1 et économie des requêtes','<p>'+pill('Non connecté','warn')+'</p><p>Aucun compteur serveur n’est disponible dans la démo. Le raccordement doit séparer lignes lues, lignes écrites, requêtes, stockage et estimation de traduction.</p><ul><li>Pagination et limites explicites.</li><li>Écritures idempotentes et opérations regroupées.</li><li>Cache des traductions et des catalogues stables.</li><li>Pas de lecture D1 à chaque image d’animation ni pour régler la fluidité.</li></ul>');}
function auditTable(list){return list.length?table(['Date','Auteur','Action','Cible',''],list.map(a=>row(new Date(a.at).toLocaleString('fr-FR'),esc(a.actor)+' · '+esc(a.role),esc(a.action),esc(a.target),btn('Détails','audit-detail','data-id="'+a.id+'"','secondary')))):empty('Aucune intervention enregistrée.');}
function audit(){return card('Traçabilité des interventions','<p>Chaque mutation conserve son auteur, sa date, la cible et les valeurs avant/après disponibles. Ce journal local peut être modifié avec les outils du navigateur ; un journal serveur protégé sera nécessaire en production.</p><div class="actions">'+btn('Exporter le journal JSON','audit-export','','secondary')+'</div>')+card('Historique',auditTable(db.audit));}
function render(){let t=tabs.find(t=>t[0]===tab)||tabs[0];$('#console-title').textContent=t[1];$('#console-nav').innerHTML=tabs.map(([id,n,icon])=>'<button data-action="tab" data-tab="'+id+'" class="'+(id===tab?'active':'')+'"><span class="nav-symbol">'+icon+'</span>'+n+'</button>').join('');$('#console-content').innerHTML=({support0304,overview,players,reports,sanctions,gifts,codes,photos,purchases,clans,referrals,team,botlab,content,promotions,services,audit})[tab]();if(tab==='botlab'&&$('#bot-group0301'))$('#bot-group0301').value=botGroup0301;if(tab==='content'){$('#content-kind').value=selection?.kind||'hero';$('#content-item').value=selection?.data?.id||catalogue($('#content-kind').value)[0].id;}if(tab==='services')$('#translation-enabled').value=db.config.translationEnabled?'on':'off';}
function readContent(){let data=JSON.parse($('#content-json').value);if(!data.id||typeof data.name!=='string')throw Error('Identifiant et nom requis.');if(data.id==='sapeur')throw Error('Le Sapeur est supprimé.');for(const k of ['hp','damage','speed','cost','priceDiamonds'])if(data[k]!=null&&(!Number.isFinite(data[k])||data[k]<0))throw Error('Valeur invalide : '+k);return {id:$('#content-kind').value+':'+data.id,kind:$('#content-kind').value,name:data.name,data};}
$('#console-content').addEventListener('change',e=>{if(e.target.id==='content-kind'){selection={kind:e.target.value,data:catalogue(e.target.value)[0]};render()}if(e.target.id==='content-item'){selection={kind:$('#content-kind').value,data:catalogue($('#content-kind').value).find(i=>i.id===e.target.value)};$('#content-json').value=JSON.stringify(selection.data,null,2)}});
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{let a=b.dataset.action,d=b.dataset;if(a==='bot-edit0301'){botSelection0301=d.id;render();return;}if(a==='bot-save0301'){saveBot0301();return;}if(a==='bot-publish0301'){let lab=BOTLAB0301.validate(botDraft0301);lab.published=true;dialog('Utiliser ces châteaux pour les essais','<p>Les cibles de pillage et de guerre seront disponibles dans le navigateur. Les identités internes restent dans cet atelier.</p>',()=>commit('botlab-save',{lab}));return;}if(a==='bot-store0301'){dialog('Enregistrer l’atelier','<p>Enregistrer les réglages locaux sans changer leur statut de publication.</p>',()=>commit('botlab-save',{lab:BOTLAB0301.validate(botDraft0301)}));return;}if(a==='bot-preview0301'){let b=botDraft0301.bots.find(b=>b.id===d.id),l=BOTLAB0301.layout(b),r=BOTLAB0301.resources(b);dialog('Château · '+b.identities[0].name,'<div class="botlab-summary0301"><b>Niveau '+b.level+'</b><b>'+l.floors+' étages</b><b>'+l.defenses.length+' défenses</b></div>'+readable030(r)+'<p>Composition de test : équilibrage définitif à effectuer.</p>',null);return;}if(a==='tab'){if(!tabs.some(t=>t[0]===d.tab))throw Error('Accès réservé au créateur');tab=d.tab;render();return}if(a==='player'){let p=db.players.find(p=>p.id===d.id),san=db.sanctions.filter(s=>s.playerId===d.id),g=db.gifts.filter(g=>g.playerIds.includes(d.id));dialog('Dossier · '+p.name,readable030(p)+'<p>'+san.length+' sanction(s), '+g.length+' distribution(s).</p>',null);return}
if(a==='warn')preview('warn',{playerId:d.player,reason:'Avertissement : merci de respecter les règles.'});if(a==='hide')preview('hide-message',{playerId:d.player});if(a==='report-close')preview('report-close',{id:d.id});if(a==='go-sanction'){tab='sanctions';render();$('#sanction-player').value=d.player;return}
if(a==='sanction-preview')preview('sanction',{playerId:$('#sanction-player').value,scope:$('#sanction-scope').value,minutes:+$('#sanction-minutes').value,permanent:$('#sanction-permanent')?.value==='yes',reason:$('#sanction-reason').value},'Vérifier la sanction');if(a==='sanction-revoke')preview('sanction-revoke',{id:d.id},'Révoquer cette sanction');
if(a==='gift-preview')previewGift030();
if(a==='gift-cancel')preview('gift-cancel',{id:d.id},'Annuler la distribution non récupérée');if(a==='code-preview')preview('code',{code:$('#code-value').value,playerId:$('#code-kind').value==='personal'?$('#code-player').value:null,limit:+$('#code-limit').value,expiresAt:new Date($('#code-expiry').value).getTime(),reward:reward()});if(a==='code-disable')preview('code-disable',{id:d.id});
if(a==='photo-review')preview('photo-review',{id:d.id,approved:d.approved==='true',reason:$('#photo-reason-'+d.id).value});if(a==='order-preview')preview('order',{orderId:$('#order-id').value,playerId:$('#order-player').value,baseDiamonds:+$('#order-diamonds').value,at:new Date($('#order-date').value).getTime()},'Reçu d’essai · aucune validation Google');if(a==='order-refund')preview('refund',{id:d.id},'Simuler un remboursement et récupérer les bonus');
if(a==='referral-preview')preview('referral-link',{parent:$('#referral-parent').value,child:$('#referral-child').value});if(a==='referral-settle')preview('referral-settle',{});if(a==='referral-qualify'){dialog('Vérifier les conditions anti-abus','<p>Niveau 7 et compte d’au moins 7 jours seront contrôlés sur les données locales.</p><label><input id="verify-identity" type="checkbox" style="width:16px"> Identités, réseaux et appareils distincts vérifiés — simulation manuelle</label>',()=>commit('referral-qualify',{child:d.child,identityVerified:$('#verify-identity').checked}));}
if(a==='admin-edit'){let admin=db.admins.find(v=>v.id===d.id);dialog('Permissions de '+admin.name,'<div class="permissions">'+RULES0291.PERMISSIONS.admin.map(p=>'<label><input type="checkbox" name="edit-permission" value="'+p+'" '+(admin.permissions.includes(p)?'checked':'')+'>'+esc(p)+'</label>').join('')+'</div>',()=>commit('admin-permissions',{id:admin.id,permissions:[...document.querySelectorAll('[name="edit-permission"]:checked')].map(e=>e.value)}));return;}if(a==='admin-preview')preview('admin-add',{playerId:$('#admin-player').value,permissions:[...document.querySelectorAll('[name="permission"]:checked')].map(e=>e.value)},'Nommer un administrateur');if(a==='admin-remove')preview('admin-remove',{id:d.id},'Révoquer immédiatement ces droits');
if(a==='content-preview'){let p=readContent(),key=p.kind==='hero'?'hero:'+p.data.id:p.kind==='troop'?'monster:'+p.data.id+':n01':p.data.asset,art=GESTION_CATALOGUE.art[key];dialog('Prévisualisation du contenu',(art?'<img class="thumbnail" src="'+art+'">':'')+'<h4>'+esc(p.name)+'</h4><pre>'+esc(JSON.stringify(p.data,null,2))+'</pre>',()=>commit('content-save',p));}if(a==='content-save')preview('content-save',readContent(),'Enregistrer le brouillon');if(a==='content-publish')preview('content-publish',{id:d.id},'Publier cette révision dans la démo');if(a==='content-rollback')preview('content-rollback',{id:d.id},'Restaurer la révision précédente');
if(a==='tournament-preview'){let rows=JSON.parse($('#tournament-rows').value),ranked=RULES0291.rankClans(rows),eventId=$('#tournament-id').value;dialog('Clôture · '+eventId,table(['Rang','Alliance','Victoires','Trésorerie de chaque ressource'],ranked.map(r=>row(r.rank,esc(r.name),r.wins,fmt(RULES0291.tournamentPrize(r.rank,1).treasury.gold))))+'<p>Les joueurs de la démo recevront leur cadeau personnel séparément. Aucun prélèvement sur l’ancienne trésorerie.</p>',()=>commit('tournament',{eventId,rows}));}
if(a==='promotion-preview')preview('promotion',{title:$('#promotion-title').value,start:new Date($('#promotion-start').value).getTime(),end:new Date($('#promotion-end').value).getTime(),rate:+$('#promotion-rate').value/100});if(a==='translation-save')preview('translation-config',{enabled:$('#translation-enabled').value==='on',budget:+$('#translation-budget').value});
if(a==='audit-detail'){let item=db.audit.find(v=>v.id===d.id);dialog('Détail de l’intervention',readable030(item),null);}if(a==='audit-export'){let url=URL.createObjectURL(new Blob([JSON.stringify(db.audit,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='Blabox_Journal_Demo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}catch(e){toast(e.message)}});
$('#console-refresh').onclick=async()=>{try{db=await request('blabox-ops-read');render();toast('Données locales actualisées.')}catch(e){toast(e.message)}};$('#console-search').oninput=e=>{let q=e.target.value.trim().toLowerCase();for(let tr of document.querySelectorAll('#console-content tbody tr'))tr.hidden=!!q&&!tr.textContent.toLowerCase().includes(q)};$('#return-player').onclick=e=>{if(window.opener){e.preventDefault();window.opener.focus();window.close()}};const label030={id:'Référence',playerId:'Joueur',playerIds:'Destinataires',name:'Nom',role:'Rôle',scope:'Périmètre',reason:'Motif',minutes:'Durée en minutes',permanent:'Définitive',title:'Titre',text:'Message',reward:'Récompenses',items:'Objets',diamonds:'Diamants',gold:'Or',elixir:'Élixir',xp:'XP',xpHero:'Héros recevant l’XP',hero:'Héros',cosmetic:'Cosmétique',audience:'Audience',clan:'Alliance',createdAt:'Créé le',at:'Date',expiresAt:'Expiration',active:'Actif',actor:'Auteur',status:'État',before:'Avant',after:'Après',action:'Intervention',target:'Cible',permissions:'Permissions',verified:'Vérifié',child:'Filleul',parent:'Parrain',identityVerified:'Identités distinctes vérifiées',orderId:'Reçu',baseDiamonds:'Diamants de base',playerId:'Joueur',source:'Origine',level:'Niveau',flag:'Drapeau',language:'Langue',changedAt:'Modification',refunded:'Remboursé',count:'Quantité',code:'Code',limit:'Utilisations maximales',qualified:'Conditions validées',senderBonus:'Bonus de l’expéditeur',recipient:'Destinataire'};
function readable030(value,key='',depth=0){if(key==='reward'&&value&&typeof value==='object')return rewardTiles030(value);if(value==null||value==='')return '<span class="muted">—</span>';if(typeof value==='boolean')return pill(value?'Oui':'Non',value?'':'warn');if(typeof value==='number'){if(/At$|^at$|^start$|^end$/.test(key)&&value>1e11)return esc(new Date(value).toLocaleString('fr-FR'));return '<b>'+fmt(value)+'</b>';}if(typeof value==='string'){let player=db.players.find(v=>v.id===value),hero=GESTION_CATALOGUE.heroes.find(v=>v.id===value);const statuses={owner:'Créateur · propriétaire',gift:'Cadeau envoyé','gift-cancel':'Cadeau annulé',sanction:'Sanction appliquée','sanction-revoke':'Sanction levée','referral-qualify':'Parrainage vérifié','referral-settle':'Bonus de parrainage traités','admin-add':'Administrateur nommé','admin-remove':'Droits administrateur révoqués','admin-permissions':'Permissions modifiées',order:'Reçu enregistré',refund:'Remboursement enregistré','photo-review':'Photo examinée','content-save':'Brouillon enregistré','content-publish':'Publication locale','referrals.read':'Consulter les dossiers','referrals.verify':'Vérifier les conditions','referrals.manage':'Traiter les bonus automatiques',player:'Un joueur',all:'Tout le monde',clan:'Une alliance',prepared:'À récupérer',claimed:'Récupéré',cancelled:'Annulé',pending:'En attente',closed:'Clôturé',chat:'Discussion',game:'Accès au jeu',creator:'Créateur',admin:'Administrateur',permanent:'Définitive'};let target=key==='target'?(db.gifts.find(v=>v.id===value)?.title||db.codes.find(v=>v.id===value)?.code):null;return '<span>'+esc(target||player?.name||hero?.name||statuses[value]||value)+'</span>';}if(Array.isArray(value))return value.length?'<div class="detail-array030">'+value.map(v=>'<div>'+readable030(v,key,depth+1)+'</div>').join('')+'</div>':'<span class="muted">Aucun</span>';return '<dl class="detail-grid030">'+Object.entries(value).filter(([k,v])=>v!==undefined&&!['id','schema','sourceSha256','token'].includes(k)).map(([k,v])=>'<div class="'+(v&&typeof v==='object'?'detail-wide030':'')+'"><dt>'+esc(label030[k]||k.replaceAll('-',' ').replaceAll('_',' '))+'</dt><dd>'+readable030(v,k,depth+1)+'</dd></div>').join('')+'</dl>';}
function asset030(id){return GESTION_CATALOGUE.art['item:'+id]||GESTION_CATALOGUE.art[id]||'';}
function rewardTiles030(r={}){let items=[];for(let k of ['diamonds','gold','elixir'])if(r[k])items.push({name:label030[k],n:r[k],url:asset030(k)});let names={'xp-small':'Potion 150 XP','xp-medium':'Potion 500 XP','xp-large':'Potion 1 500 XP','health-25':'Vie 25 %','health-50':'Vie 50 %','mana-10':'Mana +10','mana-20':'Mana +20','speed-300':'Accélérateur 5 min','speed-900':'Accélérateur 15 min','speed-3600':'Accélérateur 1 h','speed-86400':'Accélérateur 1 jour','shield-1d':'Bouclier 1 jour','energy-refill':'Recharge énergie','clan-banner':'Bannière de clan'};for(let [id,n]of Object.entries(r.items||{}))if(n)items.push({name:names[id]||id,n,url:asset030(id)||asset030('gift')});if(r.hero){let h=GESTION_CATALOGUE.heroes.find(h=>h.id===r.hero);items.push({name:h?.name||r.hero,n:1,url:GESTION_CATALOGUE.art['hero:'+r.hero]});}if(r.cosmetic){let c=GESTION_CATALOGUE.cosmetics.find(c=>c.id===r.cosmetic);items.push({name:c?.name||r.cosmetic,n:1,url:GESTION_CATALOGUE.art[c?.asset||'cosmetic:'+r.cosmetic]});}if(r.xp)items.push({name:'XP · '+(GESTION_CATALOGUE.heroes.find(h=>h.id===r.xpHero)?.name||'Héros'),n:r.xp,url:asset030('xp-medium')});return '<div class="gift-tiles030">'+items.map(i=>'<article>'+(i.url?'<img src="'+esc(i.url)+'" alt="">':'')+'<b>'+fmt(i.n)+'</b><span>'+esc(i.name)+'</span></article>').join('')+'</div>';}
rewardFields=function(){const items=[['xp-small','150 XP'],['xp-medium','500 XP'],['xp-large','1 500 XP'],['health-25','Vie 25 %'],['health-50','Vie 50 %'],['mana-10','Mana +10'],['mana-20','Mana +20'],['speed-300','5 min'],['speed-900','15 min'],['speed-3600','1 h'],['speed-86400','1 jour'],['energy-refill','Énergie'],['shield-1d','Bouclier 1 jour'],['clan-banner','Bannière']];return '<section class="reward-editor030"><h4>Ressources</h4><div class="console-form gift-resources030">'+[['diamonds','Diamants',20],['gold','Or',1000],['elixir','Élixir',1000]].map(([id,name,n])=>'<label><span><img src="'+asset030(id)+'">'+name+'</span><input id="gift-'+id+'" type="number" min="0" step="1" value="'+n+'"></label>').join('')+'</div><details class="gift-section030"><summary>Potions, accélérateurs et objets</summary><div class="gift-items030">'+items.map(([id,name])=>'<label><img src="'+(asset030(id)||asset030('gift'))+'"><span>'+name+'</span><input type="number" inputmode="numeric" min="0" value="0" data-reward-item030="'+id+'"></label>').join('')+'</div></details><details class="gift-section030"><summary>Héros, cosmétiques et XP</summary><div class="console-form">'+select('Héros à offrir','gift-hero','<option value="">Aucun</option>'+GESTION_CATALOGUE.heroes.map(h=>'<option value="'+h.id+'">'+esc(h.name)+'</option>').join(''))+select('Cosmétique','gift-cosmetic','<option value="">Aucun</option>'+GESTION_CATALOGUE.cosmetics.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join(''))+field('XP supplémentaire','gift-xp',0,'number','min="0"')+select('Héros recevant l’XP','gift-xp-hero',GESTION_CATALOGUE.heroes.map(h=>'<option value="'+h.id+'">'+esc(h.name)+'</option>').join(''))+'</div></details></section>';};
reward=function(){return {diamonds:+$('#gift-diamonds').value,gold:+$('#gift-gold').value,elixir:+$('#gift-elixir').value,items:Object.fromEntries([...document.querySelectorAll('[data-reward-item030]')].map(e=>[e.dataset.rewardItem030,Number(e.value)]).filter(([,n])=>n>0)),hero:$('#gift-hero')?.value||'',cosmetic:$('#gift-cosmetic')?.value||'',xp:+($('#gift-xp')?.value||0),xpHero:$('#gift-xp-hero')?.value||''};};
gifts=function(){let alliances=[...new Set(db.players.map(p=>p.clan).filter(Boolean))];return card('Composer un cadeau','<div class="gift-workflow030"><span>1 · Destinataires</span><span>2 · Message</span><span>3 · Récompenses</span><span>4 · Vérification</span></div><div class="console-form">'+select('Destinataires','gift-audience',options([['player','Un joueur'],['clan','Une alliance'],['all','Tout le monde']]))+'<label data-gift-target030="player">Joueur<select id="gift-player">'+playerOptions()+'</select></label><label data-gift-target030="clan" hidden>Alliance<select id="gift-clan">'+alliances.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('')+'</select></label>'+field('Titre du courrier','gift-title','Un cadeau pour toi !')+'<label class="wide">Message<textarea id="gift-text">Voici un cadeau pour te remercier.</textarea></label></div>'+rewardFields()+'<div class="actions">'+btn('Prévisualiser le courrier et vérifier les destinataires','gift-preview')+'</div>')+card('Distributions',db.gifts.length?table(['Courrier','Destinataires','État',''],db.gifts.slice().reverse().map(g=>row(esc(g.title),g.playerIds.length+' compte(s)',pill(g.status),btn('Voir le détail','gift-detail030','data-id="'+g.id+'"','secondary')+(g.status==='prepared'?btn('Annuler','gift-cancel','data-id="'+g.id+'"','danger'):'')))):empty('Aucun cadeau envoyé.'));};
function syncAudience030(){let audience=$('#gift-audience')?.value;if(!audience)return;document.querySelectorAll('[data-gift-target030]').forEach(e=>{let visible=e.dataset.giftTarget030===audience;e.hidden=!visible;for(let input of e.querySelectorAll('input,select'))input.disabled=!visible;});}
function previewGift030(){let audience=$('#gift-audience').value,p={id:crypto.randomUUID(),title:$('#gift-title').value.trim(),text:$('#gift-text').value.trim(),audience,reward:reward()};if(audience==='player')p.playerId=$('#gift-player').value;if(audience==='clan')p.clan=$('#gift-clan').value;let recipients=audience==='all'?db.players:audience==='clan'?db.players.filter(v=>v.clan===p.clan):db.players.filter(v=>v.id===p.playerId);if(!p.title||!recipients.length)throw Error('Titre et destinataires requis.');dialog('Vérifier le cadeau','<div class="gift-mail-preview030"><small>COURRIER POUR '+recipients.length+' DESTINATAIRE(S)</small><h3>'+esc(p.title)+'</h3><p>'+esc(p.text)+'</p><div class="recipient-pills030">'+recipients.map(p=>pill(p.name)).join('')+'</div><h4>Chaque destinataire reçoit</h4>'+rewardTiles030(p.reward)+'<div class="gift-distribution-total030"><h4>Total de la distribution</h4>'+rewardTiles030({...p.reward,diamonds:p.reward.diamonds*recipients.length,gold:p.reward.gold*recipients.length,elixir:p.reward.elixir*recipients.length,items:Object.fromEntries(Object.entries(p.reward.items).map(([k,n])=>[k,n*recipients.length])),xp:p.reward.xp*recipients.length})+'</div></div>',()=>commit('gift',p));}
preview=function(kind,p,title='Vérifier avant validation'){dialog(title,'<div class="operation-preview030">'+readable030(p)+'</div>',()=>commit(kind,p));};
const renderBefore030=render;render=function(){renderBefore030();syncAudience030();if(tab==='codes'){let label=$('#code-player')?.closest('label');if(label){label.hidden=$('#code-kind').value!=='personal';$('#code-player').disabled=label.hidden;}}for(let label of document.querySelectorAll('.permissions label')){let input=label.querySelector('input');if(!input)continue;let names={'referrals.read':'Consulter les dossiers','referrals.verify':'Vérifier les conditions','referrals.manage':'Traiter les bonus automatiques'};for(let node of [...label.childNodes])if(node.nodeType===3)node.remove();label.append(document.createTextNode(names[input.value]||input.value));}};
const referralsBefore030=referrals;referrals=function(){if(isCreator)return referralsBefore030();return card('Vérifications de parrainage','<div class="referral-summary030"><strong>'+db.links.filter(l=>!l.qualified).length+'</strong><span>dossier(s) en attente</span></div>')+card('Dossiers',db.links.length?table(['Parrain','Filleul','État',''],db.links.map(l=>row(esc(db.players.find(p=>p.id===l.parent)?.name||l.parent),esc(db.players.find(p=>p.id===l.child)?.name||l.child),pill(l.qualified?'Conditions validées':'À vérifier',l.qualified?'':'warn'),!l.qualified?btn('Vérifier les conditions','referral-qualify','data-child="'+l.child+'"','secondary'):''))):empty('Aucun dossier de parrainage.'))+card('Bonus automatiques',btn('Traiter les bonus éligibles après vérification','referral-settle','','secondary'));};
const overviewBefore030=overview;overview=function(){if(isCreator)return overviewBefore030();return card('Vérification des parrainages','<div class="referral-summary030"><strong>'+db.links.filter(l=>!l.qualified).length+'</strong><span>dossier(s) à examiner</span></div><div class="actions">'+btn('Ouvrir les dossiers','tab','data-tab="referrals"')+'</div>');};
document.addEventListener('change',e=>{if(e.target.id==='gift-audience')syncAudience030();if(e.target.id==='code-kind'){let personal=e.target.value==='personal',label=$('#code-player')?.closest('label');if(label){label.hidden=!personal;$('#code-player').disabled=!personal;}}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action="gift-detail030"]');if(!b)return;let g=db.gifts.find(v=>v.id===b.dataset.id);if(g)dialog(g.title,'<p>'+esc(g.text||'')+'</p>'+readable030({audience:g.audience,playerIds:g.playerIds,status:g.status,createdAt:g.createdAt,actor:g.actor})+rewardTiles030(g.reward),null);});

let botDraft0301=structuredClone(db.botLab0301||BOTLAB0301.seed()),botSelection0301=null,botGroup0301='pillage';
function botlab(){const lab=botDraft0301,b=lab.bots.find(b=>b.id===botSelection0301);return card('Atelier des châteaux · réservé au créateur','<div class="botlab-summary0301"><b>30 pillage</b><b>70 guerre</b><b>21 alliances fixes</b><b>10 alliances BOT visibles</b></div><p>Réglages locaux de test. Les apparences manquantes et l’équilibrage final restent à produire. Chaque identité peut être liée à une alliance ou rester sans alliance.</p><div class="actions">'+btn('Enregistrer l’atelier','bot-store0301')+btn('Utiliser pour les essais','bot-publish0301','','secondary')+'</div>')+(b?botEditor0301(b):'')+card('Personnages',select('Groupe','bot-group0301',options([['pillage','Pillage · 30'],['war','Guerre · 70'],['fun','BOT visibles · 150']]))+'<div class="botlab-grid0301">'+lab.bots.filter(b=>b.group===botGroup0301).map(b=>'<article class="botlab-bot0301"><img src="assets/drapeaux/'+b.flag+'.svg" alt="'+b.flag+'"><h4>'+esc(b.identities[0].name)+'</h4><b>Niveau '+b.level+'</b><small>'+({easy:'Facile',normal:'Intermédiaire',hard:'Renforcé'})[b.difficulty]+'</small>'+btn('Régler','bot-edit0301','data-id="'+b.id+'"')+btn('Aperçu','bot-preview0301','data-id="'+b.id+'"','secondary')+'</article>').join('')+'</div>')+card('Alliances','<div class="botlab-grid0301">'+lab.alliances.map(a=>'<label>'+esc(a.id.startsWith('war')?'Niveau '+a.level:'BOT visibles')+'<input data-alliance0301="'+a.id+'" value="'+esc(a.name)+'" maxlength="40"></label>').join('')+'</div>');}
function botEditor0301(b){return card('Réglages · '+esc(b.identities[0].name),'<div class="console-form">'+field('Niveau','bot-level0301',b.level,'number','min="1" max="20"')+select('Drapeau','bot-flag0301',BOTLAB0301.flags.map(f=>'<option '+(b.flag===f?'selected':'')+'>'+f+'</option>').join(''))+select('Difficulté de test','bot-difficulty0301',[['easy','Facile'],['normal','Intermédiaire'],['hard','Renforcé']].map(([k,n])=>'<option value="'+k+'" '+(b.difficulty===k?'selected':'')+'>'+n+'</option>').join(''))+field('Variante du château','bot-seed0301',b.seed,'number','min="0"')+field('Réserves · remplissage %','bot-reservePercent0301',b.reservePercent,'number','min="0" max="100"')+field('Mines · remplissage %','bot-minePercent0301',b.minePercent,'number','min="0" max="100"')+field('Réserves · ajout par heure, par ressource','bot-reservePerHour0301',b.reservePerHour,'number','min="0"')+field('Mines · ajout par heure, par ressource','bot-minePerHour0301',b.minePerHour,'number','min="0"')+'</div><h4>Trois identités alternatives</h4><div class="botlab-identities0301">'+b.identities.map((v,i)=>'<div>'+field('Nom '+(i+1),'bot-name'+i+'0301',v.name)+select('Alliance','bot-alliance'+i+'0301','<option value="">Sans alliance</option>'+botDraft0301.alliances.map(a=>'<option value="'+a.id+'" '+(v.allianceId===a.id?'selected':'')+'>'+esc(a.name)+'</option>').join(''))+'</div>').join('')+'</div><div class="actions">'+btn('Valider ces réglages','bot-save0301')+'</div>');}
function saveBot0301(){const b=structuredClone(botDraft0301.bots.find(b=>b.id===botSelection0301));for(let k of ['level','seed','reservePercent','minePercent','reservePerHour','minePerHour'])b[k]=Number($('#bot-'+k+'0301').value);b.flag=$('#bot-flag0301').value;b.difficulty=$('#bot-difficulty0301').value;b.refillAt=Date.now();b.identities=b.identities.map((v,i)=>({name:$('#bot-name'+i+'0301').value.trim(),allianceId:$('#bot-alliance'+i+'0301').value||null}));const next=structuredClone(botDraft0301);next.bots[next.bots.findIndex(v=>v.id===b.id)]=b;BOTLAB0301.validate(next);botDraft0301=next;toast('Réglages validés. Enregistre l’atelier pour les conserver.');render();}
document.addEventListener('change',e=>{if(e.target.id==='bot-group0301'){botGroup0301=e.target.value;botSelection0301=null;render();$('#bot-group0301').value=botGroup0301;}if(e.target.dataset.alliance0301){let a=botDraft0301.alliances.find(a=>a.id===e.target.dataset.alliance0301);if(a)a.name=e.target.value.trim();}});

function support0304(){const tickets=db.supportTickets0304||[];return card('Messages des joueurs',tickets.length?table(['Joueur','Message','Reçu le','État',''],[...tickets].reverse().map(t=>row(esc(t.playerName),esc(t.text.slice(0,140))+(t.image?'<br><small>Capture jointe</small>':''),new Date(t.at).toLocaleString('fr-FR'),pill(t.status==='answered'?'Répondu':'À traiter'),btn('Ouvrir et répondre','support-open0304','data-id="'+esc(t.id)+'"','secondary')))):empty('Aucune demande.'));}
const referrals0304=referrals;referrals=function(){let content=referrals0304();const box=document.createElement('div');box.innerHTML=content;for(const c of box.querySelectorAll('.console-card'))if(c.querySelector('h3')?.textContent==='Associer deux comptes d’essai')c.remove();content=box.innerHTML+(isCreator?card('Bonus automatiques',btn('Traiter les bonus éligibles','referral-settle','','secondary')):'');return card('Alertes de parrainage',(db.securityAlerts0304||[]).length?table(['Joueur','Motif','Date'],db.securityAlerts0304.map(a=>row(esc(a.playerName||a.playerId),esc(a.reason),new Date(a.at).toLocaleString('fr-FR')))):empty('Aucune tentative suspecte.'))+content;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="support-open0304"]');if(!b)return;const t=(db.supportTickets0304||[]).find(t=>t.id===b.dataset.id);if(!t)return;dialog('Demande de '+t.playerName,'<p style="white-space:pre-wrap">'+esc(t.text)+'</p>'+(t.image?'<img src="'+t.image+'" alt="Capture du joueur" style="max-width:100%;max-height:350px;object-fit:contain">':'')+(t.replies||[]).map(r=>'<p><b>Réponse :</b> '+esc(r.text)+'</p>').join('')+'<label>Réponse<textarea id="support-reply0304" maxlength="3000" rows="4"></textarea></label>',()=>commit('support-reply0304',{id:t.id,text:$('#support-reply0304').value}));});
window.console0291={role,inspect:()=>({role,tab,data:structuredClone(db)}),navigate:id=>{if(!tabs.some(t=>t[0]===id))throw Error('Accès refusé');tab=id;render()},command:async(k,p)=>{await commit(k,p);render()}};render();if(window.opener&&incoming.token)request('blabox-ops-read').then(ops=>{db=ops;DEMOOPS0291.write(db);if(tab!=='botlab')botDraft0301=structuredClone(db.botLab0301||BOTLAB0301.seed());render();}).catch(e=>toast(e.message));})();
